def read_docx_xml(path):
    with zipfile.ZipFile(path) as z:
        return z.read("word/document.xml").decode("utf-8")


def root_open_tag(xml_str):
    start = xml_str.index("<w:document")
    end = xml_str.index(">", start) + 1
    return xml_str[start:end]


# [0-9A-Fa-f]{8}만 잡으면 안 된다 — stage9의 plain_para()/caption_para()가
# _pid("P")로 만든 paraId(예: "P0000053")는 'P'가 16진수가 아니라서 그 정규식에
# 안 걸린다(이번 stage15 조립 중 실제로 발견 — 16개 문단이 diff감사망을 빠져
#나갈 뻔함). 영숫자 8자로 넓혀서 라이브 문서의 실제 paraId 관례를 전부 잡는다.
PARA_RE = re.compile(
    r'<w:p w14:paraId="([0-9A-Za-z]{8})"[^>]*?(?:/>|(?<!/)>(.*?)</w:p>)', re.DOTALL)


def para_map(xml_str):
    out = {}
    for m in PARA_RE.finditer(xml_str):
        pid, body = m.group(1), m.group(2)
        out[pid] = body or ""
    return out


def plain_text(body):
    return "".join(re.findall(r"<w:t[^>]*>([^<]*)</w:t>", body))


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--dry-run", action="store_true",
                     help="검증만 하고 실제 파일은 하나도 안 바꾼다")
    args = ap.parse_args()

    if not os.path.isfile(DOCX):
        print(f"FATAL: not found: {DOCX}")
        sys.exit(1)
    for m in MEDIA_REPLACEMENTS:
        if not os.path.isfile(m["new_source"]):
            print(f"FATAL: 새 이미지 파일 없음: {m['new_source']}")
            sys.exit(1)

    print(f"대상: {DOCX}")
    orig_xml = read_docx_xml(DOCX)
    orig_root_open = root_open_tag(orig_xml)

    # ---- 1) 앵커 유일성(count==1) 사전 검증 ----
    problems = []
    for old, new, label in REPLACEMENTS:
        c = orig_xml.count(old)
        if c != 1:
            problems.append(f"{label}: count != 1 (got {c})")
    with zipfile.ZipFile(DOCX) as z:
        for m in MEDIA_REPLACEMENTS:
            actual_md5 = hashlib.md5(z.read(m["docx_path"])).hexdigest()
            if actual_md5 != m["old_md5"]:
                problems.append(f"{m['docx_path']}: 현재 md5={actual_md5} (예상 {m['old_md5']})")
    if problems:
        print("FATAL: 앵커 검증 실패, 아무 것도 안 씀:")
        for p in problems[:20]:
            print("  -", p)
        if len(problems) > 20:
            print(f"  ... 외 {len(problems)-20}건")
        sys.exit(2)
    print(f"앵커 검증 통과: 문단 {len(REPLACEMENTS)}건 + media {len(MEDIA_REPLACEMENTS)}건")

    # ---- jc 통계(before) ----
    jc_before = Counter(re.findall(r'<w:jc w:val="(\w+)"', orig_xml))
    print(f"jc 통계(전): {dict(jc_before)}")

    # ---- 2) 적용 + 텍스트 불변 검증(문단마다) ----
    new_xml = orig_xml
    text_mismatches = []
    for old, new, label in REPLACEMENTS:
        old_text = plain_text(old)
        new_text = plain_text(new)
        if old_text != new_text:
            text_mismatches.append(label)
        assert new_xml.count(old) == 1, f"{label}: 치환 도중 앵커가 사라짐/중복됨"
        new_xml = new_xml.replace(old, new, 1)

    if text_mismatches:
        print("FATAL: 서식 전용 스테이지인데 텍스트가 바뀐 문단이 있음 — 아무 것도 안 씀:")
        for l in text_mismatches[:20]:
            print("  -", l)
        sys.exit(2)
    print(f"텍스트 불변 확인: {len(REPLACEMENTS)}건 전부 plain text 동일(diff 0)")

    # ---- 3) 전수 문단 diff 감사 ----
    old_map = para_map(orig_xml)
    new_map = para_map(new_xml)
    deleted_ids = set(old_map) - set(new_map)
    inserted_ids = set(new_map) - set(old_map)
    modified_ids = {pid for pid in (set(old_map) & set(new_map)) if old_map[pid] != new_map[pid]}

    diff_problems = []
    if deleted_ids:
        diff_problems.append(f"삭제된 paraId가 있으면 안 됨: {deleted_ids}")
    if inserted_ids:
        diff_problems.append(f"삽입된 paraId가 있으면 안 됨: {inserted_ids}")
    if modified_ids != EXPECTED_MODIFIED:
        missing = EXPECTED_MODIFIED - modified_ids
        extra = modified_ids - EXPECTED_MODIFIED
        diff_problems.append(f"수정된 paraId 불일치: 누락={missing} 예상외={extra}")

    print()
    print("전수 문단 diff 감사:")
    print(f"  삭제 {len(deleted_ids)}건 / 삽입 {len(inserted_ids)}건 / 수정 {len(modified_ids)}건")
    if diff_problems:
        print("FATAL: 의도하지 않은 변경이 섞여 있음 — 아무 것도 안 씀:")
        for p in diff_problems:
            print("  -", p)
        sys.exit(3)
    print(f"  [OK] 수정된 paraId 집합이 의도한 것과 정확히 1:1 일치 ({len(EXPECTED_MODIFIED)}건, 삭제/삽입 0건)")

    # ---- 4) 결과 검증 ----
    checks = []
    try:
        new_root = ET.fromstring(new_xml)
        checks.append(("well-formed XML", True, ""))
    except Exception as e:
        checks.append(("well-formed XML", False, str(e)))
        new_root = None

    new_root_open = root_open_tag(new_xml)
    checks.append(("루트 <w:document> 태그 불변", new_root_open == orig_root_open, ""))

    jc_after = Counter(re.findall(r'<w:jc w:val="(\w+)"', new_xml))
    print(f"jc 통계(후): {dict(jc_after)}")
    checks.append((f"jc=both 개수 증가 (전 {jc_before.get('both',0)} -> 후 {jc_after.get('both',0)})",
                    jc_after.get("both", 0) - jc_before.get("both", 0) == 524, ""))
    checks.append((f"jc=left 개수 감소분 (전 {jc_before.get('left',0)} -> 후 {jc_after.get('left',0)})",
                    jc_before.get("left", 0) - jc_after.get("left", 0) == 521, "521=524본문+3(식2+Algo1, 없던 jc가 생겼다가 아니라 새 left가 생긴 것 반영)"))

    checks.append(("챕터제목 색상(980000/EE0000) 완전 제거",
                    "980000" not in new_xml and "EE0000" not in new_xml, ""))
    checks.append(("FF0000 완전 제거", "FF0000" not in new_xml, ""))
    checks.append(("그림2 anchor 사라짐(wp:anchor 문맥에 rId55 없음)",
                    'r:embed="rId55"' in new_xml and "<wp:inline" in new_xml, ""))

    if new_root is not None:
        old_root = ET.fromstring(orig_xml)
        old_count = len(list(old_root.iter("{%s}p" % W_NS)))
        new_count = len(list(new_root.iter("{%s}p" % W_NS)))
        checks.append((f"문단 수 불변(서식 스테이지) {old_count}->{new_count}",
                        old_count == new_count, ""))
    else:
        checks.append(("문단 수 확인", False, "well-formed 실패로 건너뜀"))

    all_ok = all(ok for _, ok, _ in checks)
    print()
    print("결과 검증:")
    for name, ok, detail in checks:
        mark = "OK  " if ok else "FAIL"
        print(f"  [{mark}] {name}" + (f" — {detail}" if detail and not ok else ""))

    if not all_ok:
        print("\nFATAL: 검증 실패, 아무 파일도 안 씀.")
        sys.exit(4)

    if args.dry_run:
        print("\n--dry-run 이므로 여기서 멈춘다. 실제 파일은 하나도 안 바뀜(media 포함).")
        sys.exit(0)

    # ---- 5) 스냅샷 ----
    os.makedirs(VERSIONS_DIR, exist_ok=True)
    ts = datetime.datetime.now().strftime("%Y%m%d-%H%M")
    snapshot_path = os.path.join(VERSIONS_DIR, f"CAST_{ts}_stage15전.docx")
    shutil.copy2(DOCX, snapshot_path)
    print(f"\n스냅샷: {snapshot_path}")

    # ---- 6) 원자적 쓰기 (document.xml + media 동시) ----
    new_docx_path = DOCX + ".new"
    if os.path.exists(new_docx_path):
        os.remove(new_docx_path)

    media_new_bytes = {}
    for m in MEDIA_REPLACEMENTS:
        with open(m["new_source"], "rb") as f:
            data = f.read()
        actual_md5 = hashlib.md5(data).hexdigest()
        assert actual_md5 == m["new_md5"], f"{m['new_source']}: md5 불일치"
        media_new_bytes[m["docx_path"]] = data

    with zipfile.ZipFile(DOCX, "r") as src, \
         zipfile.ZipFile(new_docx_path, "w", zipfile.ZIP_DEFLATED) as dst:
        for item in src.infolist():
            if item.filename == "word/document.xml":
                data = new_xml.encode("utf-8")
            elif item.filename in media_new_bytes:
                data = media_new_bytes[item.filename]
            else:
                data = src.read(item.filename)
            dst.writestr(item, data)

    with zipfile.ZipFile(new_docx_path) as z:
        for m in MEDIA_REPLACEMENTS:
            got = hashlib.md5(z.read(m["docx_path"])).hexdigest()
            assert got == m["new_md5"], f"{m['docx_path']}: 쓰기 후 md5 불일치"
    print(f"media 교체 확인: {len(MEDIA_REPLACEMENTS)}건 md5 일치")

    try:
        import docx
        docx.Document(new_docx_path)
        print("python-docx 로드: OK")
    except ImportError:
        print("python-docx 미설치 — 이 검증은 건너뜀")
    except Exception as e:
        print(f"FATAL: python-docx 로드 실패: {e}")
        os.remove(new_docx_path)
        sys.exit(5)

    os.replace(new_docx_path, DOCX)
    print(f"\n완료: {DOCX} 갱신됨. 스냅샷은 {snapshot_path} 에 보존.")
    print("Word PDF 재추출로 육안 확인 권장 — 챕터제목 검정, 그림2·4 단내 배치, 본문 양쪽정렬.")


if __name__ == "__main__":
    main()
